mod transport_cache;
use algebraic::{CanonicalAlgebraicSystem, SquareRoot};
use physical_transport::RustFlow;
use serde_json::{Value, json};
use std::collections::{BTreeMap, BTreeSet};
use std::time::Instant;
use symbolica::prelude::*;
use transport_cache::*;

fn atom(s: &str) -> Result<Atom> {
    Atom::parse(s, "fivepoint_cache", Default::default())
        .map_err(|e| Error::InvalidInput(e.to_string()))
}
fn symbol(s: &str) -> Symbol {
    if let AtomView::Var(v) = atom(s).unwrap().as_view() {
        v.get_symbol()
    } else {
        panic!("symbol")
    }
}
fn coordinate_map(f: &Value, x: &Atom) -> Result<BTreeMap<Symbol, Atom>> {
    f["coordinate_names"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| {
            let n = n.as_str().unwrap();
            let a = atom(f["source_point"][n].as_str().unwrap())?;
            let b = atom(f["destination_point"][n].as_str().unwrap())?;
            Ok((symbol(n), (&a + (b - &a) * x).together().cancel()))
        })
        .collect()
}
fn scalars(p: Precision, f: &Value) -> Result<Vec<Vec<ComplexFloat>>> {
    f.as_array()
        .unwrap()
        .iter()
        .map(|r| {
            r.as_array()
                .unwrap()
                .iter()
                .map(|v| {
                    p.parse(
                        v["real"].as_str().unwrap(),
                        v["imaginary"].as_str().unwrap(),
                    )
                })
                .collect()
        })
        .collect()
}
fn coords_json(p: &CachedPoint) -> Result<Value> {
    Ok(json!(
        p.restart_coordinates()?
            .iter()
            .map(|(s, a)| (Atom::var(*s).to_string(), a.to_string()))
            .collect::<BTreeMap<_, _>>()
    ))
}
fn values_json(v: &[Vec<ComplexFloat>]) -> Value {
    json!(
        v.iter()
            .map(|r| r
                .iter()
                .map(|v| json!({"real":v.re.to_string(),"imaginary":v.im.to_string()}))
                .collect::<Vec<_>>())
            .collect::<Vec<_>>()
    )
}
fn errors_json(v: &[Vec<Float>]) -> Value {
    json!(
        v.iter()
            .map(|r| r.iter().map(ToString::to_string).collect::<Vec<_>>())
            .collect::<Vec<_>>()
    )
}
fn policy() -> impl TransportCost {
    ScaledDistance {
        scales: BTreeMap::new(),
        admissible: |_: &CachedBoundary, _: &CachedPoint| Ok(true),
    }
}
fn build(f: &Value) -> Result<CanonicalAlgebraicSystem> {
    let variables = f["coordinate_names"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| symbol(v.as_str().unwrap()))
        .collect::<Vec<_>>();
    let used = f["sparse_rational_coefficients"]
        .as_array()
        .unwrap()
        .iter()
        .map(|e| e["indices"][0].as_u64().unwrap() as usize)
        .collect::<BTreeSet<_>>();
    let mut letters = Vec::new();
    let mut matrices = Vec::new();
    for index in used {
        letters.push(atom(f["letters"][index - 1].as_str().unwrap())?);
        let mut m = vec![vec![Atom::new(); 13]; 13];
        for e in f["sparse_rational_coefficients"].as_array().unwrap() {
            let ix = e["indices"].as_array().unwrap();
            if ix[0].as_u64().unwrap() as usize == index {
                m[ix[1].as_u64().unwrap() as usize - 1][ix[2].as_u64().unwrap() as usize - 1] =
                    atom(e["coefficient"].as_str().unwrap())?;
            }
        }
        matrices.push(m);
    }
    let roots = ["tr5", "sqrtG3"]
        .into_iter()
        .map(|n| {
            Ok(SquareRoot {
                symbol: symbol(n),
                radicand: atom(
                    f["root_definitions"][n]
                        .as_str()
                        .unwrap()
                        .strip_prefix("sqrt(")
                        .unwrap()
                        .strip_suffix(')')
                        .unwrap(),
                )?,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    CanonicalAlgebraicSystem::new(symbol("eps"), &variables, &letters, &matrices, roots)
}
fn event(label: &str, start: Instant) {
    eprintln!(
        "stage {label} elapsed {:.6}s",
        start.elapsed().as_secs_f64()
    );
}
fn run() -> Result<()> {
    let global = Instant::now();
    let f: Value = serde_json::from_str(include_str!("fixture.json"))
        .map_err(|e| Error::InvalidInput(e.to_string()))?;
    let t = Instant::now();
    let system = build(&f)?;
    event("canonical_system", t);
    let canonical_seconds = t.elapsed().as_secs_f64();
    let t = Instant::now();
    let basis = (1..=13)
        .map(|j| atom(&format!("I{j}")))
        .collect::<Result<Vec<_>>>()?;
    let flow = RustFlow::new_canonical(
        system,
        &basis,
        &Atom::one(),
        Prescription::PlusI0,
        "planar 1loop PH1 regular real patch 0<=x<=1/500 on exact PH1-to-PH6 affine line; principal roots and inherited PH1 logarithm sheet",
    )?;
    event("identity", t);
    let identity_seconds = t.elapsed().as_secs_f64();
    let germ = RootGerm {
        sheets: BTreeMap::from([
            (symbol("tr5"), RootSheet::Principal),
            (symbol("sqrtG3"), RootSheet::Principal),
        ]),
    };
    let source_p = Precision::decimal(160)?;
    let range = EpsilonRange::new(0, 4)?;
    let errors = f["boundary_absolute_errors_by_epsilon"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| {
            r.as_array()
                .unwrap()
                .iter()
                .map(|v| source_p.parse(v.as_str().unwrap(), "0").map(|z| z.re))
                .collect()
        })
        .collect::<Result<Vec<Vec<_>>>>()?;
    let source = CachedBoundary {
        identity: flow.identity().clone(),
        point: CachedPoint::Exact(coordinate_map(&f, &Atom::new())?)
            .with_root_germ(germ.clone())?,
        kind: PointKind::Physical,
        range,
        coefficients: scalars(source_p, &f["boundary_by_epsilon"])?,
        accuracy: BoundaryAccuracy::supplied(
            128,
            source_p.bits,
            errors,
            "DiffExp source numIntegrals-1loop.m: 132-digit absolute accuracy metadata, conservative 1e-130 inexact input errors, advertised128; exact epsilon0 coefficients retained; source values are supplied, not AMF-generated",
        )?,
    };
    let mut cache = RustFlowCache::default();
    cache.insert(source.clone())?;
    event("source_inserted", global);
    let options = FlowOptions {
        digits: 20,
        guard_digits: 40,
        series_order: 64,
        max_steps: 1000,
        ..Default::default()
    };
    let context = RunContext::default();
    let p = Precision::decimal(90)?;
    let mut output = json!({"case":"full13_planar_regular_canonical_cache","dimension":13,"epsilon_range":[0,4],"coordinates":"exact six-dimensional PH1-to-PH6 affine line","source":"supplied PH1 reference with recorded132-digit absolute metadata; advertised128; 1e-130 inexact errors","canonical_seconds":canonical_seconds,"identity_seconds":identity_seconds,"options":{"digits":20,"guard_digits":40,"series_order":64},"steps":[]});
    let mut destinations = Vec::new();
    let mut values = Vec::new();
    for denom in [1000, 500] {
        let x = Atom::num(Rational::from((1, denom)));
        let destination = coordinate_map(&f, &x)?;
        let target = CachedPoint::Exact(destination.clone()).with_root_germ(germ.clone())?;
        let admitted =
            flow.identity()
                .conditions_admit_straight_path(&source.point, &target, p, 20)?;
        if !admitted {
            return Err(Error::Unsupported(format!("source-to-{x} not regular")));
        }
        let t = Instant::now();
        let answer = flow.evaluate_to(
            &mut cache,
            &destination,
            Some(&germ),
            range,
            &options,
            &context,
            &policy(),
        )?;
        let seconds = t.elapsed().as_secs_f64();
        event(&format!("cached_endpoint_{denom}"), t);
        let step = json!({"x":x.to_string(),"seconds":seconds,"source":coords_json(&answer.starting_point)?,"target":coords_json(&answer.boundary.point)?,"inserted_points":answer.inserted_points,"bank_len":cache.len(),"verified_digits":answer.boundary.accuracy.verified_digits(),"working_bits":answer.boundary.accuracy.working_bits(),"accepted_steps":answer.transport.as_ref().map(|s|s.diagnostics.steps),"rejected_steps":answer.transport.as_ref().map(|s|s.diagnostics.rejected_steps),"values":values_json(&answer.boundary.coefficients),"comparison_errors_including_input":errors_json(answer.boundary.accuracy.comparison_errors())});
        output["steps"].as_array_mut().unwrap().push(step);
        destinations.push(destination);
        values.push(answer.boundary.coefficients);
    }
    if output["steps"][1]["source"] != output["steps"][0]["target"] {
        return Err(Error::Accuracy(
            "second request did not choose first destination".into(),
        ));
    }
    let bank_path = std::path::Path::new("target/fivepoint-canonical-cache/bank");
    let t = Instant::now();
    cache.save(bank_path)?;
    let save_seconds = t.elapsed().as_secs_f64();
    let t = Instant::now();
    let mut loaded = RustFlowCache::load(bank_path)?;
    let load_seconds = t.elapsed().as_secs_f64();
    let t = Instant::now();
    let hit = flow.evaluate_to(
        &mut loaded,
        &destinations[1],
        Some(&germ),
        range,
        &options,
        &context,
        &policy(),
    )?;
    let hit_seconds = t.elapsed().as_secs_f64();
    if hit.transport.is_some() || hit.inserted_points != 0 {
        return Err(Error::Accuracy("repeat performed transport".into()));
    }
    output["persistence"] = json!({"save_seconds":save_seconds,"load_seconds":load_seconds,"exact_hit_seconds":hit_seconds,"entries":loaded.len(),"exact_repeat":true});
    event("reload_exact_hit", global);
    let mut direct_cache = RustFlowCache::default();
    direct_cache.insert(source)?;
    let mut matching_cache = direct_cache.clone();
    let matching_clock = Instant::now();
    let matching = flow.evaluate_to(
        &mut matching_cache,
        &destinations[1],
        Some(&germ),
        range,
        &options,
        &context,
        &policy(),
    )?;
    let matching_seconds = matching_clock.elapsed().as_secs_f64();
    let mut matching_error = p.real(0);
    for (a, b) in values[1]
        .iter()
        .flatten()
        .zip(matching.boundary.coefficients.iter().flatten())
    {
        let delta = p.norm(&p.sub(a, b));
        if delta > matching_error {
            matching_error = delta;
        }
    }
    if matching_error > p.tolerance(20) {
        return Err(Error::Accuracy(
            "matching-settings direct comparison failed".into(),
        ));
    }
    output["matching_settings_direct"] = json!({
        "seconds":matching_seconds,"digits":20,"guard_digits":40,"series_order":64,
        "starting_point":coords_json(&matching.starting_point)?,
        "working_bits":matching.boundary.accuracy.working_bits(),
        "verified_digits":matching.boundary.accuracy.verified_digits(),
        "accepted_steps":matching.transport.as_ref().map(|s|s.diagnostics.steps),
        "rejected_steps":matching.transport.as_ref().map(|s|s.diagnostics.rejected_steps),
        "max_absolute_difference":matching_error.to_string(),
        "values":values_json(&matching.boundary.coefficients),
        "comparison_errors_including_input":errors_json(matching.boundary.accuracy.comparison_errors())
    });
    event("matching_settings_direct", matching_clock);
    let direct_options = FlowOptions {
        digits: 40,
        guard_digits: 50,
        series_order: 96,
        max_steps: 1000,
        ..Default::default()
    };
    output["direct_checks"] = json!([]);
    for (j, destination) in destinations.iter().enumerate() {
        let mut independent_cache = direct_cache.clone();
        let t = Instant::now();
        let direct = flow.evaluate_to(
            &mut independent_cache,
            destination,
            Some(&germ),
            range,
            &direct_options,
            &context,
            &policy(),
        )?;
        let seconds = t.elapsed().as_secs_f64();
        let mut abs = p.real(0);
        let mut rel = p.real(0);
        let mut errors = Vec::new();
        for (a, b) in values[j]
            .iter()
            .flatten()
            .zip(direct.boundary.coefficients.iter().flatten())
        {
            let delta = p.norm(&p.sub(a, b));
            let norm = p.norm(b);
            let scale = if norm > p.real(1) { norm } else { p.real(1) };
            let scaled = delta.clone() / scale;
            if delta > abs {
                abs = delta.clone();
            }
            if scaled > rel {
                rel = scaled;
            }
            errors.push(delta.to_string());
        }
        if rel > p.tolerance(20) {
            return Err(Error::Accuracy(format!("direct mismatch {rel}")));
        }
        output["direct_checks"].as_array_mut().unwrap().push(json!({"endpoint_index":j,"seconds":seconds,"digits":40,"guard_digits":50,"series_order":96,"max_absolute_difference":abs.to_string(),"max_scaled_difference":rel.to_string(),"all65_absolute_differences":errors,"values":values_json(&direct.boundary.coefficients),"comparison_errors_including_input":errors_json(direct.boundary.accuracy.comparison_errors()),"verified_digits":direct.boundary.accuracy.verified_digits(),"working_bits":direct.boundary.accuracy.working_bits(),"accepted_steps":direct.transport.as_ref().map(|s|s.diagnostics.steps),"rejected_steps":direct.transport.as_ref().map(|s|s.diagnostics.rejected_steps)}));
        event(&format!("direct_endpoint_{j}"), t);
    }
    output["elapsed_seconds"] = json!(global.elapsed().as_secs_f64());
    output["status"] = json!("passed");
    std::fs::write(
        "target/fivepoint-canonical-cache/result.json",
        serde_json::to_vec_pretty(&output).map_err(|e| Error::InvalidInput(e.to_string()))?,
    )?;
    println!(
        "passed full13 cache: all65 coefficients checked at each point, progressive nearest source, binary reload and exact repeat"
    );
    Ok(())
}
fn main() {
    if let Err(e) = run() {
        eprintln!("ERROR {e:?}");
        std::process::exit(1)
    }
}

