from decimal import Decimal, localcontext
from pathlib import Path
import hashlib,json,re
base=Path(__file__).resolve().parent
rust=json.load(open(base/'result.json')); original=json.load(open(base/'original/result.json'))
def number(s):
 s=s.strip().replace(' ', '')
 s=re.sub(r'`{1,2}[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)?','',s)
 return Decimal(s.replace('*^','e'))
def pair(cell,wl=False):
 return (number(cell['real_wolfram' if wl else 'real']),number(cell['imaginary_wolfram' if wl else 'imaginary']))
def magnitude(z):return (z[0]*z[0]+z[1]*z[1]).sqrt()
with localcontext() as ctx:
 ctx.prec=180
 comparisons=[]
 for key,values in [('progressive',rust['steps'][1]['values']),('direct_refined',rust['direct_checks'][1]['values'])]:
  abs_errors=[]; scaled=[]
  for k in range(5):
   for j in range(13):
    a=pair(values[k][j]);b=pair(original['endpoint_values'][j][k],True)
    error=magnitude((a[0]-b[0],a[1]-b[1]));abs_errors.append(error);scaled.append(error/max(Decimal(1),magnitude(b)))
  comparisons.append({'path':key,'coefficient_count':65,'max_absolute_difference':str(max(abs_errors)),'max_scaled_difference':str(max(scaled)),'all_absolute_differences':[str(v) for v in abs_errors],'passes20_absolute_digits':max(abs_errors)<Decimal('1e-20'),'passes20_scaled_digits':max(scaled)<Decimal('1e-20')})
 result={'status':'passed' if all(v['passes20_absolute_digits'] for v in comparisons) else 'failed','scope':'All65 coefficients at exact PH1+(PH6-PH1)/500 against fresh unchanged DiffExp implementation, supplied PH1 boundary; independent implementation agreement, not automatic AMF or amplitude','original_settings':original['settings'],'comparisons':comparisons,'files':{str(p.relative_to(base)):{'sha256':hashlib.file_digest(open(p,'rb'),'sha256').hexdigest(),'bytes':p.stat().st_size} for p in [base/'result.json',base/'original/result.json',base/'original/runner.json']}}
 (base/'original-comparison.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k!='comparisons'}));print([(x['path'],x['max_absolute_difference']) for x in comparisons]);assert result['status']=='passed'
